mapper.select:
SELECT 


  handover.deleted = 0
  AND handover.tenant_id = #{tenantId}

    AND fulfillment.erp_tenant_id = #{query.erpTenantId}


    AND fulfillment.warehouse_id = #{query.warehouseId}


    AND handover.handover_status = #{query.fulfillmentStatus}


    AND handover.create_time >= #{query.startDate}


    AND handover.create_time < DATE_ADD(#{query.endDate}, INTERVAL 1 DAY)


ORDER BY handover.create_time DESC, handover.id DESC
